/**
 * Language features for code embedded in HTML-like documents: JavaScript in `<script>` blocks and
 * CSS / SCSS / Less in `<style>` blocks.
 *
 * Each document of a registered language gets hidden models that contain only the embedded code, with
 * everything else blanked out (newlines kept) so positions line up with the document. Monaco's own
 * TypeScript and CSS workers then answer for those hidden models. This is the "embedded document"
 * approach VS Code's HTML support uses.
 *
 * - JavaScript uses `monaco.typescript.getJavaScriptWorker()`.
 * - CSS validation comes from monaco's CSS support validating the hidden model. Completion, hover and
 *   colours need `monaco.css.getWorker()`, which nr-monaco-build adds; without it they are skipped.
 *
 * `html` and `handlebars` are registered by RED.editor.codeEditor.monaco. Other HTML-like languages
 * (e.g. one registered by a node or plugin) can opt in with `registerEmbeddedLanguages()`, and can
 * adjust the JavaScript (wrap it, add type declarations) for their own runtime.
 *
 * @namespace RED.editor.codeEditor.monacoEmbedded
 */
RED.editor.codeEditor.monacoEmbedded = (function () {

    const SCRIPT_TYPES = /^\s*(module|text\/javascript|application\/javascript|text\/ecmascript|application\/ecmascript|text\/babel)?\s*$/i;
    const MUSTACHE = /\{\{\{?[\s\S]*?\}?\}\}/g;
    const STYLE_LANGUAGES = { scss: "scss", less: "less" };

    /** language ids that are served by monaco's html worker (see registerHTMLLanguage) */
    const htmlWorkerLanguages = new Set();
    /** language id -> { options, disposables } */
    const registrations = new Map();
    /** host model uri -> { host, language, js, styles: Map<languageId, state>, disposables } */
    const hosts = new Map();
    let listening = false;

    /**
     * Finds the inline JavaScript `<script>` blocks.
     * @param {string} text - the document
     * @returns {{start: number, end: number, attributes: string}[]} offsets of each script's content
     */
    function findScriptRegions(text) {
        const regions = [];
        for (const m of text.matchAll(/<script\b([^>]*)>([\s\S]*?)<\/script\s*>/gi)) {
            const attributes = m[1];
            if (/\bsrc\s*=/i.test(attributes)) {
                continue;
            }
            const type = /\btype\s*=\s*(["']?)([^"'\s>]*)\1/i.exec(attributes);
            if (type && !SCRIPT_TYPES.test(type[2])) {
                continue; // e.g. text/x-template, application/json
            }
            const start = m.index + m[0].indexOf(">") + 1;
            regions.push({ start, end: start + m[2].length, attributes });
        }
        return regions;
    }

    /**
     * Finds the `<style>` blocks, with the stylesheet language from a `lang` attribute.
     * @param {string} text - the document
     * @returns {{start: number, end: number, languageId: string}[]}
     */
    function findStyleRegions(text) {
        const regions = [];
        for (const m of text.matchAll(/<style\b([^>]*)>([\s\S]*?)<\/style\s*>/gi)) {
            const lang = /\blang\s*=\s*(["']?)(\w+)\1/i.exec(m[1]);
            const start = m.index + m[0].indexOf(">") + 1;
            regions.push({ start, end: start + m[2].length, languageId: (lang && STYLE_LANGUAGES[lang[2].toLowerCase()]) || "css" });
        }
        return regions;
    }

    /**
     * Builds a hidden document: the regions' text at their original offsets, everything else blanked,
     * plus optional inserted text, with offset mapping both ways.
     * @param {string} text - the host document
     * @param {{start: number, end: number}[]} regions - the parts to keep
     * @param {object} [options]
     * @param {{at: number, text: string}[]} [options.insertions] - text to insert at host offsets
     * @param {boolean} [options.mustache] - replace `{{...}}` in the regions with a same-length `null`
     *   placeholder, for templates that are rendered with mustache before they reach the browser
     * @param {string} [options.trailer] - text appended at the end
     */
    function createEmbeddedDocument(text, regions, options) {
        options = options || {};
        const insertions = (options.insertions || []).slice();
        if (options.trailer) {
            insertions.push({ at: text.length, text: options.trailer });
        }
        insertions.sort((a, b) => a.at - b.at);
        const keep = new Uint8Array(text.length);
        for (const r of regions) {
            keep.fill(1, r.start, r.end);
        }
        let source = text;
        if (options.mustache) {
            source = text.replace(MUSTACHE, (m) => (m.length >= 4 ? "null" + " ".repeat(m.length - 4) : " ".repeat(m.length)));
        }
        let out = "";
        let next = 0;
        for (let i = 0; i <= text.length; i++) {
            while (next < insertions.length && insertions[next].at === i) {
                out += insertions[next++].text;
            }
            if (i === text.length) {
                break;
            }
            const ch = text[i];
            out += (keep[i] || ch === "\n" || ch === "\r") ? (keep[i] ? source[i] : ch) : " ";
        }
        return {
            text: out,
            regions,
            /** @returns {boolean} true if a host offset is inside one of the regions (end inclusive) */
            isInRegion(offset) {
                return regions.some(r => offset >= r.start && offset <= r.end);
            },
            /** Maps a host offset to the hidden document */
            toEmbedded(offset) {
                let delta = 0;
                for (const ins of insertions) {
                    if (ins.at > offset) { break; }
                    delta += ins.text.length;
                }
                return offset + delta;
            },
            /** Maps a hidden document offset to the host, or -1 if it is inside inserted text */
            toHost(offset) {
                let delta = 0;
                for (const ins of insertions) {
                    const at = ins.at + delta;
                    if (offset < at) { break; }
                    if (offset < at + ins.text.length) { return -1; }
                    delta += ins.text.length;
                }
                return offset - delta;
            }
        };
    }

    function displayPartsToString(parts) {
        return (parts || []).map(p => p.text).join("");
    }

    function tagsToString(tags) {
        return (tags || []).map(tag => {
            const text = Array.isArray(tag.text) ? displayPartsToString(tag.text) : (tag.text || "");
            return "*@" + tag.name + "*" + (text ? " - " + text.replace(/\n/g, "  \n") : "");
        }).join("\n\n");
    }

    /** Converts a TypeScript ScriptElementKind to a monaco CompletionItemKind */
    function convertTsKind(kind) {
        const k = monaco.languages.CompletionItemKind;
        switch (kind) {
            case "primitive type": case "keyword": return k.Keyword;
            case "var": case "local var": case "let": case "const": case "parameter": return k.Variable;
            case "property": case "getter": case "setter": return k.Field;
            case "function": case "local function": case "method": case "construct": case "call": case "index": return k.Function;
            case "enum": return k.Enum;
            case "module": case "external module name": return k.Module;
            case "class": case "local class": return k.Class;
            case "interface": case "type": return k.Interface;
            case "warning": return k.Text;
        }
        return k.Property;
    }

    /** Converts an LSP CompletionItemKind (used by the CSS worker) to a monaco CompletionItemKind */
    function convertLspKind(kind) {
        const k = monaco.languages.CompletionItemKind;
        const map = {
            1: k.Text, 2: k.Method, 3: k.Function, 4: k.Constructor, 5: k.Field, 6: k.Variable, 7: k.Class,
            8: k.Interface, 9: k.Module, 10: k.Property, 11: k.Unit, 12: k.Value, 13: k.Enum, 14: k.Keyword,
            15: k.Snippet, 16: k.Color, 17: k.File, 18: k.Reference, 19: k.Folder, 20: k.EnumMember,
            21: k.Constant, 22: k.Struct, 23: k.Event, 24: k.Operator, 25: k.TypeParameter
        };
        return map[kind] || k.Property;
    }

    function lspRange(range) {
        return new monaco.Range(range.start.line + 1, range.start.character + 1, range.end.line + 1, range.end.character + 1);
    }

    function lspMarkdown(contents) {
        if (!contents) { return []; }
        const list = Array.isArray(contents) ? contents : [contents];
        return list.map(c => {
            if (typeof c === "string") { return { value: c }; }
            if (c.kind === "plaintext") { return { value: c.value.replace(/[\\`*_{}[\]()#+\-.!]/g, "\\$&") }; }
            if (c.language) { return { value: "```" + c.language + "\n" + c.value + "\n```" }; }
            return { value: c.value };
        });
    }

    function getTypeScriptApi() {
        // monaco 0.55 moved monaco.languages.typescript to monaco.typescript (same for css and html)
        return monaco.typescript?.getJavaScriptWorker ? monaco.typescript : monaco.languages.typescript;
    }

    function getCssApi() {
        return monaco.css?.cssDefaults ? monaco.css : monaco.languages.css;
    }

    function getHtmlApi() {
        return monaco.html?.registerHTMLLanguageService ? monaco.html : monaco.languages.html;
    }

    /** Retries once: monaco rejects ("... not registered!") until the language's mode has started */
    async function getWorker(getter, ...args) {
        try {
            return await getter(...args);
        } catch (err) {
            await new Promise(resolve => setTimeout(resolve, 250));
            return getter(...args);
        }
    }

    async function getJavaScriptWorker(uri) {
        return (await getWorker(() => getTypeScriptApi().getJavaScriptWorker()))(uri);
    }

    async function getCssWorker(languageId, uri) {
        return (await getWorker(() => getCssApi().getWorker(languageId)))(uri);
    }

    function canUseCssWorker() {
        return typeof getCssApi()?.getWorker === "function";
    }

    //#region hidden models

    function buildJavaScript(host, options) {
        const text = host.getValue();
        const findRegions = options.javascript.regions || findScriptRegions;
        const regions = findRegions(text);
        const insertions = [];
        if (options.javascript.wrap) {
            regions.forEach((region, index) => {
                insertions.push(...(options.javascript.wrap(text, region, index) || []));
            });
        }
        // a module keeps each document's top level names to itself
        return createEmbeddedDocument(text, regions, { insertions, mustache: options.mustache, trailer: "\nexport {}\n" });
    }

    function buildStyles(host, options) {
        const text = host.getValue();
        const findRegions = options.css.regions || findStyleRegions;
        const byLanguage = new Map();
        for (const region of findRegions(text)) {
            const id = region.languageId || "css";
            if (!byLanguage.has(id)) { byLanguage.set(id, []); }
            byLanguage.get(id).push(region);
        }
        const docs = new Map();
        for (const [id, regions] of byLanguage) {
            docs.set(id, createEmbeddedDocument(text, regions, { mustache: options.mustache }));
        }
        return docs;
    }

    function syncHost(state) {
        const options = registrations.get(state.language)?.options;
        if (!options || state.host.isDisposed()) {
            return;
        }
        if (options.javascript) {
            const doc = buildJavaScript(state.host, options);
            if (!state.js) {
                const model = monaco.editor.createModel(doc.text, "javascript", monaco.Uri.parse(state.host.uri.toString() + ".embedded.js"));
                state.js = { model, doc };
            } else {
                state.js.doc = doc;
                state.js.model.setValue(doc.text);
            }
        }
        if (options.css) {
            const docs = buildStyles(state.host, options);
            for (const [id, doc] of docs) {
                const existing = state.styles.get(id);
                if (existing) {
                    existing.doc = doc;
                    existing.model.setValue(doc.text);
                } else {
                    const model = monaco.editor.createModel(doc.text, id, monaco.Uri.parse(state.host.uri.toString() + ".embedded." + id));
                    state.styles.set(id, { model, doc });
                }
            }
            // a style language that is no longer used: drop its hidden model
            for (const [id, style] of state.styles) {
                if (!docs.has(id)) {
                    style.model.dispose();
                    state.styles.delete(id);
                    monaco.editor.setModelMarkers(state.host, "embedded-" + id, []);
                }
            }
        }
    }

    function attach(host) {
        const key = host.uri.toString();
        const registration = registrations.get(host.getLanguageId());
        if (!registration || hosts.has(key) || host.isDisposed()) {
            return;
        }
        const state = { host, language: host.getLanguageId(), js: null, styles: new Map(), disposables: [] };
        hosts.set(key, state);
        addExtraLibs(state.language);
        syncHost(state);
        state.disposables.push(host.onDidChangeContent(() => syncHost(state)));
        state.disposables.push(host.onWillDispose(() => detach(host)));
    }

    function detach(host) {
        const key = host.uri.toString();
        const state = hosts.get(key);
        if (!state) {
            return;
        }
        hosts.delete(key);
        state.disposables.forEach(d => d.dispose());
        if (state.js && !state.js.model.isDisposed()) {
            state.js.model.dispose();
        }
        for (const [id, style] of state.styles) {
            if (!style.model.isDisposed()) { style.model.dispose(); }
            if (!host.isDisposed()) { monaco.editor.setModelMarkers(host, "embedded-" + id, []); }
        }
        if (!host.isDisposed()) {
            monaco.editor.setModelMarkers(host, "embedded-javascript", []);
        }
        removeExtraLibs(state.language);
    }

    function addExtraLibs(languageId) {
        const registration = registrations.get(languageId);
        const libs = registration?.options.javascript?.extraLibs;
        registration.hostCount = (registration.hostCount || 0) + 1;
        if (libs && libs.length && !registration.extraLibs) {
            const ts = getTypeScriptApi();
            registration.extraLibs = libs.map(lib => ts.javascriptDefaults.addExtraLib(lib.content, lib.filePath));
        }
    }

    function removeExtraLibs(languageId) {
        const registration = registrations.get(languageId);
        if (!registration) {
            return;
        }
        registration.hostCount = Math.max(0, (registration.hostCount || 1) - 1);
        // only while a document of this language is open, so other editors never see them
        if (registration.hostCount === 0 && registration.extraLibs) {
            registration.extraLibs.forEach(d => d.dispose());
            registration.extraLibs = null;
        }
    }

    /** Finds which hidden document a host position is in */
    function locate(host, position) {
        const state = hosts.get(host.uri.toString());
        if (!state) {
            return null;
        }
        const hostOffset = host.getOffsetAt(position);
        if (state.js && state.js.doc.isInRegion(hostOffset)) {
            return { state, kind: "javascript", embedded: state.js, offset: state.js.doc.toEmbedded(hostOffset), fileName: state.js.model.uri.toString() };
        }
        for (const [languageId, style] of state.styles) {
            if (style.doc.isInRegion(hostOffset)) {
                return { state, kind: "css", languageId, embedded: style, offset: hostOffset, fileName: style.model.uri.toString() };
            }
        }
        return null;
    }

    /** Converts a TypeScript text span in the hidden JavaScript to a host range, or null if it can't be mapped */
    function spanToHostRange(at, span) {
        const start = at.embedded.doc.toHost(span.start);
        const end = at.embedded.doc.toHost(span.start + span.length);
        if (start < 0 || end < 0) {
            return null;
        }
        const p1 = at.state.host.getPositionAt(start);
        const p2 = at.state.host.getPositionAt(end);
        return new monaco.Range(p1.lineNumber, p1.column, p2.lineNumber, p2.column);
    }

    /** The JavaScript identifier around a position (word patterns for HTML-like languages exclude `$`) */
    function identifierRange(host, position) {
        const line = host.getLineContent(position.lineNumber);
        const before = /[\w$]*$/.exec(line.slice(0, position.column - 1))[0];
        const after = /^[\w$]*/.exec(line.slice(position.column - 1))[0];
        return new monaco.Range(position.lineNumber, position.column - before.length, position.lineNumber, position.column + after.length);
    }

    /** Copies the markers monaco puts on a hidden model onto its host document */
    function mirrorMarkers(uris) {
        for (const uri of uris) {
            const key = uri.toString();
            for (const state of hosts.values()) {
                if (state.host.isDisposed()) { continue; }
                let embedded = null;
                let owner = null;
                if (state.js && state.js.model.uri.toString() === key) {
                    embedded = state.js;
                    owner = "embedded-javascript";
                } else {
                    for (const [id, style] of state.styles) {
                        if (style.model.uri.toString() === key) {
                            embedded = style;
                            owner = "embedded-" + id;
                        }
                    }
                }
                if (!embedded || embedded.model.isDisposed()) { continue; }
                const markers = [];
                for (const marker of monaco.editor.getModelMarkers({ resource: embedded.model.uri })) {
                    const start = embedded.doc.toHost(embedded.model.getOffsetAt({ lineNumber: marker.startLineNumber, column: marker.startColumn }));
                    const end = embedded.doc.toHost(embedded.model.getOffsetAt({ lineNumber: marker.endLineNumber, column: marker.endColumn }));
                    if (start < 0 || !embedded.doc.isInRegion(start)) {
                        continue; // in text added by a wrap() hook, or outside the embedded code
                    }
                    const p1 = state.host.getPositionAt(start);
                    const p2 = state.host.getPositionAt(end < 0 ? start : end);
                    // copy the marker data only: fields such as modelVersionId belong to the hidden model
                    markers.push({
                        severity: marker.severity,
                        message: marker.message,
                        code: marker.code,
                        source: marker.source,
                        tags: marker.tags,
                        startLineNumber: p1.lineNumber,
                        startColumn: p1.column,
                        endLineNumber: p2.lineNumber,
                        endColumn: p2.column
                    });
                }
                monaco.editor.setModelMarkers(state.host, owner, markers);
            }
        }
    }

    //#endregion

    //#region providers

    function registerProviders(languageId) {
        const disposables = [];
        const registration = registrations.get(languageId);

        disposables.push(monaco.languages.registerCompletionItemProvider(languageId, {
            triggerCharacters: [".", ":", "-", "/"],
            async provideCompletionItems(host, position, context) {
                const at = locate(host, position);
                if (!at) {
                    return;
                }
                if (at.kind === "javascript") {
                    return javascriptCompletions(at, host, position, registration.options.javascript);
                }
                return cssCompletions(at, host, position);
            },
            async resolveCompletionItem(item) {
                const ref = item.embeddedJavaScript;
                if (!ref) {
                    return item;
                }
                const worker = await getJavaScriptWorker(ref.uri);
                const details = await worker.getCompletionEntryDetails(ref.fileName, ref.offset, item.label);
                if (!details) {
                    return item;
                }
                const documentation = [displayPartsToString(details.documentation), tagsToString(details.tags)].filter(Boolean).join("\n\n");
                return Object.assign({}, item, { detail: displayPartsToString(details.displayParts), documentation: { value: documentation } });
            }
        }));

        disposables.push(monaco.languages.registerHoverProvider(languageId, {
            async provideHover(host, position) {
                const at = locate(host, position);
                if (!at) {
                    return;
                }
                if (at.kind === "javascript") {
                    const worker = await getJavaScriptWorker(at.embedded.model.uri);
                    const info = await worker.getQuickInfoAtPosition(at.fileName, at.offset);
                    if (!info || host.isDisposed()) {
                        return;
                    }
                    const signature = displayPartsToString(info.displayParts);
                    const hidden = registration.options.javascript.hiddenNames;
                    if (hidden && hidden.test(signature.replace(/^\([^)]*\)\s*/, ""))) {
                        return;
                    }
                    const documentation = [displayPartsToString(info.documentation), tagsToString(info.tags)].filter(Boolean).join("\n\n");
                    return {
                        range: spanToHostRange(at, info.textSpan) || undefined,
                        contents: [{ value: "```ts\n" + signature + "\n```" }, { value: documentation }]
                    };
                }
                if (!canUseCssWorker()) {
                    return;
                }
                const worker = await getCssWorker(at.languageId, at.embedded.model.uri);
                const hover = await worker.doHover(at.fileName, { line: position.lineNumber - 1, character: position.column - 1 });
                if (!hover || host.isDisposed()) {
                    return;
                }
                return { range: hover.range ? lspRange(hover.range) : undefined, contents: lspMarkdown(hover.contents) };
            }
        }));

        disposables.push(monaco.languages.registerSignatureHelpProvider(languageId, {
            signatureHelpTriggerCharacters: ["(", ","],
            async provideSignatureHelp(host, position, token, context) {
                const at = locate(host, position);
                if (!at || at.kind !== "javascript") {
                    return;
                }
                const worker = await getJavaScriptWorker(at.embedded.model.uri);
                const triggerReason = context && context.triggerKind === monaco.languages.SignatureHelpTriggerKind.TriggerCharacter && context.triggerCharacter
                    ? { kind: context.isRetrigger ? "retrigger" : "characterTyped", triggerCharacter: context.triggerCharacter }
                    : { kind: "invoked" };
                const info = await worker.getSignatureHelpItems(at.fileName, at.offset, { triggerReason });
                if (!info || host.isDisposed()) {
                    return;
                }
                // leave out helpers added by a wrap() hook, e.g. when the cursor is inside their arguments
                const hidden = registration.options.javascript.hiddenNames;
                if (hidden && info.items.every(item => hidden.test(displayPartsToString(item.prefixDisplayParts)))) {
                    return;
                }
                const signatures = info.items.map(item => {
                    const parameters = item.parameters.map(p => ({ label: displayPartsToString(p.displayParts), documentation: displayPartsToString(p.documentation) }));
                    const label = displayPartsToString(item.prefixDisplayParts) +
                        parameters.map(p => p.label).join(displayPartsToString(item.separatorDisplayParts)) +
                        displayPartsToString(item.suffixDisplayParts);
                    return { label, parameters, documentation: { value: [displayPartsToString(item.documentation), tagsToString(item.tags)].filter(Boolean).join("\n\n") } };
                });
                return { value: { signatures, activeSignature: info.selectedItemIndex, activeParameter: info.argumentIndex }, dispose() {} };
            }
        }));

        disposables.push(monaco.languages.registerDefinitionProvider(languageId, {
            async provideDefinition(host, position) {
                const at = locate(host, position);
                if (!at || at.kind !== "javascript") {
                    return;
                }
                const worker = await getJavaScriptWorker(at.embedded.model.uri);
                const entries = await worker.getDefinitionAtPosition(at.fileName, at.offset);
                if (!entries || host.isDisposed()) {
                    return;
                }
                // only definitions inside this document can be shown
                return entries.filter(e => e.fileName === at.fileName)
                    .map(e => ({ uri: host.uri, range: spanToHostRange(at, e.textSpan) }))
                    .filter(e => e.range);
            }
        }));

        disposables.push(monaco.languages.registerColorProvider(languageId, {
            async provideDocumentColors(host) {
                const state = hosts.get(host.uri.toString());
                if (!state || !state.styles.size || !canUseCssWorker()) {
                    return [];
                }
                const colors = [];
                for (const [id, style] of state.styles) {
                    const worker = await getCssWorker(id, style.model.uri);
                    const found = await worker.findDocumentColors(style.model.uri.toString());
                    for (const c of found || []) {
                        colors.push({ color: c.color, range: lspRange(c.range) });
                    }
                }
                return colors;
            },
            async provideColorPresentations(host, info) {
                const at = locate(host, { lineNumber: info.range.startLineNumber, column: info.range.startColumn });
                if (!at || at.kind !== "css" || !canUseCssWorker()) {
                    return [];
                }
                const worker = await getCssWorker(at.languageId, at.embedded.model.uri);
                const range = { start: { line: info.range.startLineNumber - 1, character: info.range.startColumn - 1 }, end: { line: info.range.endLineNumber - 1, character: info.range.endColumn - 1 } };
                const presentations = await worker.getColorPresentations(at.fileName, info.color, range);
                return (presentations || []).map(p => ({
                    label: p.label,
                    textEdit: p.textEdit ? { range: lspRange(p.textEdit.range), text: p.textEdit.newText } : undefined,
                    additionalTextEdits: (p.additionalTextEdits || []).map(e => ({ range: lspRange(e.range), text: e.newText }))
                }));
            }
        }));
        return disposables;
    }

    async function javascriptCompletions(at, host, position, options) {
        const worker = await getJavaScriptWorker(at.embedded.model.uri);
        const info = await worker.getCompletionsAtPosition(at.fileName, at.offset);
        if (!info || host.isDisposed()) {
            return;
        }
        const wordRange = identifierRange(host, position);
        const hidden = options.hiddenNames;
        const demoted = options.demotedNames;
        const suggestions = info.entries.filter(e => !(hidden && hidden.test(e.name))).map(entry => {
            const range = (entry.replacementSpan && spanToHostRange(at, entry.replacementSpan)) || wordRange;
            return {
                label: entry.name,
                insertText: entry.name,
                sortText: (demoted && demoted.test(entry.name) ? "~" : "") + entry.sortText,
                kind: convertTsKind(entry.kind),
                range,
                tags: entry.kindModifiers && entry.kindModifiers.indexOf("deprecated") !== -1 ? [monaco.languages.CompletionItemTag.Deprecated] : [],
                embeddedJavaScript: { uri: at.embedded.model.uri, fileName: at.fileName, offset: at.offset }
            };
        });
        return { suggestions };
    }

    async function cssCompletions(at, host, position) {
        if (!canUseCssWorker()) {
            return;
        }
        const worker = await getCssWorker(at.languageId, at.embedded.model.uri);
        const list = await worker.doComplete(at.fileName, { line: position.lineNumber - 1, character: position.column - 1 });
        if (!list || host.isDisposed()) {
            return;
        }
        const word = host.getWordUntilPosition(position);
        const wordRange = new monaco.Range(position.lineNumber, word.startColumn, position.lineNumber, word.endColumn);
        const suggestions = list.items.map(item => {
            const edit = item.textEdit;
            const result = {
                label: item.label,
                insertText: edit ? edit.newText : (item.insertText || item.label),
                sortText: item.sortText,
                filterText: item.filterText,
                documentation: typeof item.documentation === "string" ? item.documentation : item.documentation ? { value: item.documentation.value } : undefined,
                detail: item.detail,
                kind: convertLspKind(item.kind),
                range: edit ? lspRange(edit.range || edit.replace) : wordRange,
                tags: item.tags
            };
            if (item.insertTextFormat === 2) {
                result.insertTextRules = monaco.languages.CompletionItemInsertTextRule.InsertAsSnippet;
            }
            if (item.command && item.command.command === "editor.action.triggerSuggest") {
                result.command = { id: "editor.action.triggerSuggest", title: item.command.title };
            }
            return result;
        });
        return { suggestions, incomplete: list.isIncomplete };
    }

    //#endregion

    /**
     * Adds JavaScript and CSS language features to the `<script>` and `<style>` blocks of a language.
     * Calling it again for the same language replaces its options.
     *
     * @param {string} languageId - an HTML-like monaco language, e.g. "html"
     * @param {object} [options]
     * @param {boolean} [options.mustache] - treat `{{...}}` in the blocks as a placeholder value
     * @param {object|false} [options.javascript] - `false` to turn JavaScript features off
     * @param {function(string): {start: number, end: number}[]} [options.javascript.regions] - finds the
     *   JavaScript (offsets of the code); defaults to inline `<script>` blocks
     * @param {function(string, object, number): {at: number, text: string}[]} [options.javascript.wrap] - text
     *   to insert around a region in the hidden JavaScript, e.g. to give `this` a type. Called with the
     *   document, the region and its index; returns host offsets to insert at. Positions in the inserted
     *   text are never shown to the user.
     * @param {{content: string, filePath: string}[]} [options.javascript.extraLibs] - type declarations
     *   added while a document of this language is open
     * @param {RegExp} [options.javascript.hiddenNames] - completions and hovers to leave out, e.g. helper
     *   functions used by `wrap`
     * @param {RegExp} [options.javascript.demotedNames] - completions to list after the others
     * @param {object|false} [options.css] - `false` to turn CSS features off
     * @param {function(string): {start: number, end: number, languageId: string}[]} [options.css.regions] -
     *   finds the stylesheets; defaults to `<style>` blocks (`lang="scss"` / `lang="less"` supported)
     * @returns {{dispose: function}} removes the features again
     * @memberof RED.editor.codeEditor.monacoEmbedded
     */
    function registerEmbeddedLanguages(languageId, options) {
        options = Object.assign({ javascript: {}, css: {} }, options);
        const existing = registrations.get(languageId);
        if (existing) {
            existing.options = options;
            for (const state of hosts.values()) {
                if (state.language === languageId) {
                    syncHost(state);
                }
            }
            return { dispose: () => unregister(languageId) };
        }
        const registration = { options, hostCount: 0, extraLibs: null, disposables: [] };
        registrations.set(languageId, registration);
        registration.disposables = registerProviders(languageId);
        if (!listening) {
            listening = true;
            monaco.editor.onDidCreateModel(model => attach(model));
            monaco.editor.onDidChangeModelLanguage(({ model }) => {
                detach(model);
                attach(model);
            });
            // copy after the event: markers set while monaco is still delivering it are not drawn
            let pending = null;
            monaco.editor.onDidChangeMarkers(uris => {
                if (!pending) {
                    pending = new Map();
                    setTimeout(() => {
                        const batch = [...pending.values()];
                        pending = null;
                        mirrorMarkers(batch);
                    }, 0);
                }
                uris.forEach(uri => pending.set(uri.toString(), uri));
            });
        }
        monaco.editor.getModels().filter(m => m.getLanguageId() === languageId).forEach(attach);
        return { dispose: () => unregister(languageId) };
    }

    function unregister(languageId) {
        const registration = registrations.get(languageId);
        if (!registration) {
            return;
        }
        for (const state of [...hosts.values()]) {
            if (state.language === languageId) {
                detach(state.host);
            }
        }
        registration.disposables.forEach(d => d.dispose());
        registrations.delete(languageId);
    }

    /**
     * Registers monaco's HTML language service (completion, hover, formatting, folding, ...) for another
     * HTML-like language, and makes sure the editor starts monaco's html worker for it. Monaco asks for a
     * worker labelled with the language id, which otherwise falls back to the plain editor worker.
     *
     * @param {string} languageId - a monaco language registered with `monaco.languages.register()`
     * @param {object} [options] - HTML language service options, merged over the html defaults
     * @returns {object} what monaco's registerHTMLLanguageService returns (dispose() to remove it)
     * @memberof RED.editor.codeEditor.monacoEmbedded
     */
    function registerHTMLLanguage(languageId, options) {
        const html = getHtmlApi();
        htmlWorkerLanguages.add(languageId);
        return html.registerHTMLLanguageService(languageId, Object.assign({}, html.htmlDefaults && html.htmlDefaults.options, options));
    }

    /**
     * @param {string} label - the worker label monaco asks MonacoEnvironment for
     * @returns {boolean} true if the label is a language served by monaco's html worker
     * @memberof RED.editor.codeEditor.monacoEmbedded
     */
    function usesHtmlWorker(label) {
        return htmlWorkerLanguages.has(label);
    }

    return {
        registerEmbeddedLanguages,
        registerHTMLLanguage,
        usesHtmlWorker,
        // exported for tests
        findScriptRegions,
        findStyleRegions,
        createEmbeddedDocument
    };
})();

if (typeof module !== "undefined" && module.exports) {
    module.exports = RED.editor.codeEditor.monacoEmbedded;
}
